arguments:
{"script":"# Create var_snapshot.txt with value and type info
{
  if [ "${var+x}" = x ]; then
    printf "VALUE_RAW:\n";
    printf '%s' "$var";
    printf "\n";
    printf "DECLARE_OUTPUT:\n";
    declare -p var 2>/dev/null || true;
    printf "ENV_EXPORT_CHECK:\n";
    env | grep -m1 '^var=' 2>/dev/null || true;
  else
    printf "UNSET\n";
  fi
} > var_snapshot.txt

# Produce normalized form: trim whitespace and remove surrounding single or double quotes
normalized=$(printf '%s' "$var" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e 's/^"\(.*\)"$/\1/' -e "s/^'\\(.*\\)'$/\\1/")
printf '%s' "$normalized" > var_normalized.txt

# Record whether normalized appears to be a whole number (optional leading sign, digits only)
if printf '%s' "$normalized" | grep -Eq '^[+-]?[0-9]+$'; then
  echo "whole_number_like: yes" > var_meta.txt
  is_int=yes
else
  echo "whole_number_like: no" > var_meta.txt
  is_int=no
fi

# Combine into var_check_ready.txt with concise summary of evidence and readiness criteria (no final decision)
{
  echo "normalized_value: '$normalized'"
  echo "regex_match_digits_with_optional_sign: $( [ "$is_int" = yes ] && echo yes || echo no )"
  echo "readiness_criteria: digits with optional leading +/-; no surrounding whitespace or quotes; no decimal point; no exponent; single-line digits"
  echo "evidence: var_snapshot.txt contains raw value and declare output; var_normalized.txt contains the cleaned textual form; var_meta.txt indicates whether the cleaned form matches the digits-with-optional-sign pattern"
  echo "final_decision: not made in this file"
} > var_check_ready.txt

# Output final answer exactly: yes if integer, otherwise no
printf '%s' "$([ "$is_int" = yes ] && echo yes || echo no)"
"}
